import {categoryOrder,sortProducts} from './product-order.js';
import {createOrderExperience} from './order-experience.js';
import {createSaleHistory} from './sale-history.js';
import {createSaleVoice} from './sale-voice.js';
export function createUpgrade(ctx){
 const {db,h,notice,operate}=ctx;const {esc,money,date,field,text,qtyInput,select,products,confirmCount,table,row,noShift}=h;
  let checkoutRequest={},checkoutButtonVisible=true,checkoutObserver,cart=[],filters={inventory:'',category:'',order:'',status:'pending',store:'all'},countDrafts=new Map(),lastSale=null,saleSearch='',saleCategory='',saleLimit=12,cartShift=null;
 const cleanPayment=()=>({discount:'0',cash:'',yape:'',reference:'',note:'',mode:'cash',manual:false,received:'',autoCash:false,voiceTranscript:''});let payment=cleanPayment();
 const state=()=>ctx.state();const localDate=value=>new Date((value?new Date(value):new Date()).getTime()-5*3600000).toISOString().slice(0,16);
 const when=value=>new Date(`${value}:00-05:00`).toISOString();
 const normal=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const amountInput=(name,value=0)=>qtyInput(name,value,'0.01');
 let indexed=null;
 function indexes(){
  const {data,shift}=state(),shiftId=shift?.id||null;
  if(indexed?.data===data&&indexed.shiftId===shiftId)return indexed;
  const products=new Map((data.products||[]).map(p=>[p.id,p])),counts=new Map(),stock=new Map(),sold=new Map(),search=new Map();
  for(const p of products.values())search.set(p.id,normal(`${p.name} ${p.category} ${p.sku}`));
  for(const c of data.counts||[])if(c.shift_id===shiftId){counts.set(c.product_id,c);stock.set(c.product_id,Number(c.opening_qty||0));}
  for(const m of data.movements||[])if(m.shift_id===shiftId)stock.set(m.product_id,(stock.get(m.product_id)||0)+Number(m.quantity));
  for(const sale of data.sales||[])if(sale.shift_id===shiftId&&sale.status==='completed')for(const line of sale.charito_sale_lines||[])sold.set(line.product_id,(sold.get(line.product_id)||0)+Number(line.quantity));
  return indexed={data,shiftId,products,counts,stock,sold,search};
 }
 const expected=id=>indexes().stock.get(id)||0;
 const saleHistory=createSaleHistory(ctx);
 const paid=id=>Number(state().data.balances.find(b=>b.order_id===id)?.paid||0);
 const balance=o=>(o.status==='cancelled'?0:Number(o.total))-paid(o.id);

 function countTable(mode){const {data,storeId,shift}=state(),opening=mode==='opening';const key=`${storeId}/${opening?'opening':shift?.id}`;const entries=opening?data.products.map(p=>({product_id:p.id,opening_qty:0,closing_qty:null,price_snapshot:p.price})):data.counts.filter(c=>c.shift_id===shift?.id);
  const product=c=>indexes().products.get(c.product_id);
  const ordered=sortProducts(entries,data.products,{product,price:c=>c.price_snapshot}),present=new Set(entries.map(c=>product(c)?.category)),categories=categoryOrder(data.products).filter(c=>present.has(c));
  const rows=ordered.map(c=>{const p=indexes().products.get(c.product_id);const value=countDrafts.get(`${key}/${c.product_id}`)??(opening?'':c.closing_qty??'');const needsCount=!opening&&c.physical_closing_qty!=null&&Number(c.physical_closing_qty)+Number(c.closing_movement_delta)<0;const cells=[`<div class="countname">${esc(p?.name)}<small>${esc(p?.category)} · ${esc(p?.unit)}</small>${needsCount?'<small class="warn">Volver a contar</small>':''}</div>`,money(c.price_snapshot),esc(c.opening_qty),...(!opening&&shift?.sales_mode==='direct'?[esc(expected(c.product_id))]:[]),qtyInput(c.product_id,value,p?.quantity_step||1,'0',needsCount)];return row(cells).replace('<tr>',`<tr data-stock-row data-category="${esc(p?.category)}" data-search="${esc(normal(`${p?.name} ${p?.category} ${p?.sku}`))}">`);});
  return `${!opening&&shift?.inventory_revision!=null?`<input type="hidden" name="inventory_revision" value="${esc(shift.inventory_revision)}">`:''}<div class="filters"><label>Buscar producto<input data-filter="inventory" placeholder="Nombre, categoría o código" value="${esc(filters.inventory)}"></label><label>Categoría<select data-filter="category"><option value="">Todas</option>${categories.map(c=>`<option ${c===filters.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label><span data-count-visible>${entries.length} productos</span></div>${table(['Producto','Precio','Inicial',...(!opening&&shift?.sales_mode==='direct'?['Stock esperado']:[]),opening?'Conteo inicial':'Conteo final'],rows).replace('<table>', '<table class="inventory-table">').replace('class="tablewrap"', 'class="tablewrap inventory-wrap"')}`;
 }
 const orderUI=createOrderExperience({...ctx,filters:()=>filters});
 const orders=()=>orderUI.orders();
 const detail=(...args)=>orderUI.detail(...args);
 const lineTotal=(id,qty)=>Math.round(Math.round(priceFor(id)*100)*qty)/100;
 const totals=()=>cart.reduce((n,l)=>n+Math.round(lineTotal(l.product_id,l.qty)*100),0)/100;
 const priceFor=id=>Number(indexes().counts.get(id)?.price_snapshot||0);
 const netTotal=()=>Math.round((totals()-Number(payment.discount||0))*100)/100;
 function ensureCartShift(){const current=state().shift?.id||null;if(cartShift&&cartShift!==current){cart=[];payment=cleanPayment();checkoutRequest={};voiceSale.reset();}cartShift=current;}
 function validQty(product,qty){return Number.isFinite(qty)&&qty>0&&Math.abs(qty/Number(product.quantity_step||1)-Math.round(qty/Number(product.quantity_step||1)))<1e-7;}
 function addProduct(id,amount){ensureCartShift();const {data}=state();const p=data.products.find(p=>p.id===id);if(!p)throw Error('Producto no disponible.');const qty=Number(amount??p.quantity_step??1),line=cart.find(l=>l.product_id===id);if(!validQty(p,qty))throw Error('Revisa la cantidad y presentación.');if((line?.qty||0)+qty>expected(id))throw Error('Stock insuficiente para agregar este producto.');if(line)line.qty+=qty;else cart.push({product_id:id,qty});initializePayment();refreshCart();}
 function reduceProduct(id){ensureCartShift();const line=cart.find(l=>l.product_id===id),p=indexes().products.get(id);if(!line||!p)return;const qty=Math.round((line.qty-Number(p.quantity_step||1))*1000)/1000;if(qty<=0)cart=cart.filter(l=>l.product_id!==id);else line.qty=qty;initializePayment();refreshCart();}
 const favoriteKey=()=>`charito-favorites/${state().user.id}`;const favorites=()=>{try{return JSON.parse(localStorage.getItem(favoriteKey())||'[]');}catch{return [];}};
 function catalogue(){
  const {data}=state(),idx=indexes(),fav=new Set(favorites()),tokens=normal(saleSearch).split(/\s+/).filter(Boolean),inCart=new Map(cart.map(l=>[l.product_id,l.qty]));
  const found=data.products.filter(p=>idx.counts.has(p.id)&&(!saleCategory||p.category===saleCategory)&&tokens.every(t=>idx.search.get(p.id).includes(t)))
   .sort((a,b)=>Number(fav.has(b.id))-Number(fav.has(a.id))||(idx.sold.get(b.id)||0)-(idx.sold.get(a.id)||0));
  return `<div class="catalog-result-count" role="status">${found.length} productos</div><div class="product-grid">${found.slice(0,saleLimit).map(p=>{
   const selected=inCart.get(p.id)||0,available=Math.max(0,(idx.stock.get(p.id)||0)-selected),step=Number(p.quantity_step||1),label=esc(`${p.category} · ${p.name}`);
   return `<div class="product-card ${selected?'in-cart':''}"><button type="button" class="favorite-button" data-favorite="${p.id}" aria-label="Favorito ${label}" aria-pressed="${fav.has(p.id)}">${fav.has(p.id)?"★":"☆"}</button><button type="button" class="product-tile" data-add-product="${p.id}" aria-label="Añadir ${label}" ${available<step?'disabled':''}><span class="product-category">${esc(p.category)}</span><strong>${esc(p.name)}</strong><span class="product-price">${money(priceFor(p.id))}<small> / ${esc(p.unit)}</small></span><span class="product-stock">${available<step?'Sin stock':`Stock: ${esc(available)}`}</span></button>${selected?`<div class="catalog-quantity" role="group" aria-label="Cantidad de ${label}"><button type="button" data-reduce-product="${p.id}" aria-label="Reducir ${label}">−</button><output aria-label="Cantidad en la venta" aria-live="polite">${esc(selected)}${p.unit==='ciento'?'<small>ciento</small>':''}</output><button type="button" data-add-product="${p.id}" aria-label="Aumentar ${label}" ${available<step?'disabled':''}>+</button></div>`:''}</div>`;
  }).join('')}</div>${!found.length?'<p class="empty">No hay productos con esta búsqueda.</p>':''}${found.length>saleLimit?'<button type="button" class="secondary load-more" data-more-products>Mostrar más productos</button>':''}`;
 }
 function cartView(){const {data}=state();return cart.length?cart.map((l,i)=>{const p=data.products.find(p=>p.id===l.product_id),step=Number(p?.quantity_step||1);return `<div class="cart-line"><div class="cart-product"><strong>${esc(p?.name)}</strong><small>${esc(p?.category)} · ${money(priceFor(l.product_id))} / ${esc(p?.unit)}</small></div><strong class="cart-amount">${money(lineTotal(l.product_id,l.qty))}</strong><div class="quantity-control"><button type="button" class="secondary" data-cart-step="${i}" data-delta="-${step}" aria-label="Reducir ${esc(p?.name)}">−</button><input aria-label="Cantidad de ${esc(p?.name)}" type="number" inputmode="decimal" min="${step}" step="${step}" value="${l.qty}" data-cart-qty="${i}" required><button type="button" class="secondary" data-cart-step="${i}" data-delta="${step}" aria-label="Aumentar ${esc(p?.name)}">+</button></div><button type="button" class="cart-remove" data-cart-remove="${i}" aria-label="Quitar ${esc(p?.name)}">Quitar</button></div>`;}).join(''):'<div class="cart-empty">Sin productos</div>';}
 function initializePayment(){if(!payment.manual){const total=netTotal();payment.cash=payment.mode==='yape'?'0':String(Math.max(0,total));payment.yape=payment.mode==='yape'?String(Math.max(0,total)):'0';}}
 function checkoutView(){initializePayment();const total=netTotal();return `<form data-form="sale" ${checkoutRequest.request?`data-request="${esc(checkoutRequest.request)}" data-payload="${esc(checkoutRequest.payload)}"`:''}><div class="sale-checkout-grid"><section class="checkout-items"><div class="checkout-section-title"><h3>Productos</h3><span class="checkout-item-count">${cart.length}</span></div><div class="cart">${cartView()}</div><button type="button" class="secondary checkout-continue" data-dialog-close>Seguir agregando</button></section><section class="checkout-payment"><div class="checkout-total"><span>Total</span><strong id="sale-total">${money(total)}</strong></div><div class="payment-tabs" aria-label="Medio de pago">${[['cash','Efectivo'],['yape','Yape'],['mixed','Ambos']].map(([mode,label])=>`<button type="button" data-payment-mode="${mode}" aria-pressed="${payment.mode===mode}" class="${payment.mode===mode?'selected':''}">${label}</button>`).join('')}</div><div class="fields payment-split">${field('Efectivo (S/)',amountInput('cash',payment.cash))}${field('Yape (S/)',amountInput('yape',payment.yape))}</div><p id="payment-balance" class="payment-error" aria-live="polite" hidden></p><div class="cash-received">${field('Recibido (S/)',qtyInput('received',payment.received,'0.01','0',false))}<div class="tender-shortcuts">${[['exact','Exacto'],[20,'S/20'],[50,'S/50'],[100,'S/100']].map(([n,label])=>`<button type="button" class="secondary" data-tender="${n}">${label}</button>`).join('')}</div><div id="sale-change" class="change-box" aria-live="polite" hidden></div></div><details class="sale-advanced" ${Number(payment.discount)>0||payment.note||payment.reference?'open':''}><summary>Descuento y nota</summary>${field('Descuento (S/)',amountInput('discount',payment.discount))}<div ${payment.mode==='cash'?'hidden':''}>${field('Referencia Yape',`<input name="reference" value="${esc(payment.reference)}">`)}</div>${field('Nota / motivo del descuento',`<input name="note" value="${esc(payment.note)}">`)}</details><div class="checkout-submit-area"><button class="checkout-submit" ${cart.length?'':'disabled'}>Confirmar cobro</button></div></section></div></form>`;}
 function rememberCheckout(f=document.querySelector('[data-form="sale"]')){if(f?.dataset.request)checkoutRequest={request:f.dataset.request,payload:f.dataset.payload||''};}
 function updateSaleSummary(){document.querySelectorAll('[data-checkout-total]').forEach(el=>el.textContent=money(netTotal()));document.querySelectorAll('[data-checkout-count]').forEach(el=>el.textContent=`${cart.length} ${cart.length===1?'producto':'productos'}`);document.querySelectorAll('[data-open-checkout]').forEach(b=>b.disabled=!cart.length);const dock=document.querySelector('.sale-checkout-dock');if(dock)dock.hidden=!cart.length||checkoutButtonVisible;const count=document.querySelector('.checkout-item-count');if(count)count.textContent=cart.length;}
 function refreshCatalogue(){const el=document.querySelector('#sale-products');if(el)el.innerHTML=catalogue();}
 function refreshCheckout(focus){rememberCheckout();if(ctx.dialogs.is('sale-checkout')){ctx.dialogs.update('sale-checkout',checkoutView());updatePaymentView();if(focus)ctx.dialogs.element.querySelector(focus)?.focus({preventScroll:true});}}
 function refreshCart(focus){refreshCatalogue();updateSaleSummary();if(ctx.dialogs.is('sale-checkout'))refreshCheckout(focus);ctx.flush();}
 function openCheckout(){ensureCartShift();if(!cart.length)throw Error('Agrega productos a la venta.');voiceSale.cancel();const panel=document.querySelector('#voice-sale-panel');if(panel)panel.outerHTML=voiceSale.view();ctx.dialogs.open({key:'sale-checkout',title:'Cobrar venta',wide:true,confirmDiscard:false,body:checkoutView(),focus:'[data-payment-mode="'+payment.mode+'"]',onClose:({dialog})=>{rememberCheckout(dialog.querySelector('[data-form="sale"]'));ctx.flush();}});ctx.dialogs.element.classList.add('sale-checkout-dialog');ctx.dialogs.element.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-cart-qty]')){e.preventDefault();e.target.dispatchEvent(new Event('change',{bubbles:true}));e.target.blur();}});updatePaymentView();}
 function sales(){const {data,shift}=state();if(!shift)return noShift();if(shift.sales_mode!=='direct')return '<div class="warn">Este turno registra ventas por conteo físico. Las ventas individuales se activan al abrir el próximo turno.</div>';ensureCartShift();initializePayment();
  const present=new Set(data.products.filter(p=>indexes().counts.has(p.id)).map(p=>p.category)),categories=categoryOrder(data.products).filter(c=>present.has(c));
  return `<div class="sales-page"><section class="card sales-catalog"><div class="sales-catalog-heading"><h2>Productos</h2><div class="sales-catalog-actions"><button type="button" class="secondary sale-voice-toggle" data-voice-open aria-expanded="${voiceSale.snapshot().opened}">Dictar</button><button type="button" class="sales-checkout-inline" data-open-checkout ${cart.length?'':'disabled'}>Cobrar <strong data-checkout-total>${money(netTotal())}</strong></button></div></div>${voiceSale.view()}<label class="sales-search"><span class="sr-only">Buscar producto</span><input type="search" data-sale-search value="${esc(saleSearch)}" placeholder="Buscar producto, categoría o código" autocomplete="off"></label><div class="category-chips" aria-label="Categorías"><button type="button" data-sale-category="" class="${saleCategory===''?'selected':''}" aria-pressed="${saleCategory===''}">Todos</button>${categories.map(c=>`<button type="button" data-sale-category="${esc(c)}" class="${c===saleCategory?'selected':''}" aria-pressed="${c===saleCategory}">${esc(c)}</button>`).join('')}</div><div id="sale-products">${catalogue()}</div></section><div class="sale-checkout-dock" ${cart.length?'':'hidden'}><button type="button" data-open-checkout><span class="checkout-dock-label"><span data-checkout-count>${cart.length} ${cart.length===1?'producto':'productos'}</span><strong>Cobrar</strong></span><strong data-checkout-total>${money(netTotal())}</strong><span aria-hidden="true">→</span></button></div>${saleHistory.view()}</div>`;
 }
 function updatePaymentView(){updateSaleSummary();const f=document.querySelector('[data-form="sale"]');if(!f)return;f.elements.cash.closest('.field').hidden=payment.mode!=='mixed';f.elements.yape.closest('.field').hidden=payment.mode!=='mixed';const total=netTotal();if(payment.autoCash&&payment.mode!=='yape')payment.cash=String(Math.max(0,Math.round((total-Number(payment.yape||0))*100)/100));const cash=Number(payment.cash||0),yape=Number(payment.yape||0),diff=Math.round((total-cash-yape)*100)/100;
  document.querySelector('#sale-total').textContent=money(total);
  // Preserve the browser's in-progress decimal text (for example, '1.') while typing.
  for(const name of ['cash','yape','discount','received']){const input=f.elements[name],value=String(payment[name]);if(document.activeElement!==input&&input.value!==value)input.value=value;}
  f.elements.discount.step='0.01';f.elements.discount.min='0';f.elements.discount.max=String(totals());f.elements.note.required=Number(payment.discount)>0;
  const discount=Number(payment.discount||0),invalidDiscount=!Number.isFinite(discount)||discount<0||discount>totals()||Math.abs(discount*100-Math.round(discount*100))>1e-7;
  f.elements.discount.setCustomValidity(invalidDiscount?'El descuento debe estar entre cero y el subtotal, con hasta dos decimales.':'');
  const received=payment.received===''?null:Number(payment.received),invalidReceived=received!==null&&(!Number.isFinite(received)||received<cash||Math.abs(received*100-Math.round(received*100))>1e-7);f.querySelector('.cash-received').hidden=cash<=0;const change=f.querySelector('#sale-change'),changeAmount=received===null?0:Math.max(0,Math.round((received-cash)*100)/100);change.hidden=!invalidReceived&&changeAmount===0;change.innerHTML=invalidReceived?(!Number.isFinite(received)||received<0||Math.abs(received*100-Math.round(received*100))>1e-7?'Importe no válido.':`Faltan ${money(cash-received)}`):`<span>Vuelto</span><strong>${money(changeAmount)}</strong>`;change.classList.toggle('payment-error',invalidReceived);
  const invalid=invalidDiscount||invalidReceived||!Number.isFinite(total)||!Number.isFinite(cash)||!Number.isFinite(yape)||total<0||cash<0||yape<0||Math.abs(Math.round(cash*100)-cash*100)>1e-7||Math.abs(Math.round(yape*100)-yape*100)>1e-7||cart.some(l=>l.qty>expected(l.product_id));const status=f.querySelector('#payment-balance');status.textContent=invalidReceived?'':invalid?'Revisa los importes o el stock.':diff>0?`Falta asignar ${money(diff)}`:diff<0?`El cobro supera el total en ${money(-diff)}`:'';status.hidden=!status.textContent;f.querySelector('.checkout-submit').disabled=!!f.dataset.busy||!cart.length||invalid||diff!==0;f.querySelectorAll('[data-tender]').forEach(b=>b.disabled=!!f.dataset.busy||b.dataset.tender!=='exact'&&Number(b.dataset.tender)<cash);
 }
 function applyFilters(){updatePaymentView();let visible=0;document.querySelectorAll('[data-stock-row]').forEach(r=>{r.hidden=!(r.dataset.search.includes(normal(filters.inventory))&&(!filters.category||r.dataset.category===filters.category));if(!r.hidden)visible++;});const count=document.querySelector('[data-count-visible]');if(count)count.textContent=`${visible} productos visibles`;let orders=0;document.querySelectorAll('[data-order-row]').forEach(r=>{r.hidden=!(r.dataset.search.includes(normal(filters.order))&&(filters.status==='all'||r.dataset.status===filters.status)&&(filters.store==='all'||r.dataset.store===filters.store));if(!r.hidden)orders++;});const empty=document.querySelector('#order-empty');if(empty)empty.hidden=orders>0;}
 async function submit(action,x,f){if(await orderUI.submit(action,x,f))return true;if(await saleHistory.submit(action,x,f))return true;
  if(action==='cart_add'){addProduct(x.product_id,Number(x.qty));return true;}if(action!=='sale')return false;
  ensureCartShift();if(!cart.length)throw Error('El turno cambió o el carrito está vacío. Revisa la tienda y agrega los productos.');
  const cash=Number(x.cash),received=x.received===''||x.received===undefined?null:Number(x.received),owner=state().user?.id;if(cash>0&&received!==null&&(!Number.isFinite(received)||received<cash))throw Error('El efectivo entregado no alcanza.');
  const audit=cash>0&&received!==null?`Efectivo entregado ${money(received)}; vuelto ${money(Math.round((received-cash)*100)/100)}.`:'';
  const inputs=[...f.querySelectorAll('input,select,textarea')],disabled=inputs.map(el=>el.disabled);inputs.forEach(el=>el.disabled=true);try{const result=await operate('sale',{shift_id:state().shift.id,lines:cart,cash,yape:Number(x.yape),discount:Number(x.discount),note:[x.note,audit,payment.voiceTranscript?`Dictado original: ${payment.voiceTranscript}`:''].filter(Boolean).join('\n'),reference:x.reference},f);
  if(state().user?.id!==owner)return true;lastSale=result.id;cart=[];payment=cleanPayment();checkoutRequest={};voiceSale.reset();ctx.flush();await ctx.load();if(state().user?.id!==owner)return true;ctx.render();receipt(result.id);notice('Venta guardada.');return true;}finally{if(f.isConnected){rememberCheckout(f);inputs.forEach((el,i)=>el.disabled=disabled[i]);}}
 }

 function receipt(id){const {data}=state();const sale=data.sales.find(s=>s.id===id);if(!sale)return;const lines=sale.charito_sale_lines||[];const html=`<div class="receipt"><h3>Charito’s</h3>${sale.status==='voided'?'<strong class="receipt-void">VENTA ELIMINADA</strong>':''}<p>Venta · ${esc(id.slice(0,8))}<br>${date(sale.created_at)}</p>${lines.map(l=>`<div class="summaryrow"><span>${esc(h.productName(l.product_id))} × ${esc(l.quantity)}</span><span>${money(Number(l.quantity)*Number(l.unit_price))}</span></div>`).join('')}<p>Descuento ${money(sale.discount)}<br><strong>Total ${money(sale.total)}</strong></p><small>Ticket interno · sin valor tributario</small>${sale.note?`<p class="small">${esc(sale.note).replace(/\n/g,'<br>')}</p>`:''}<div class="actions"><button type="button" data-print>Imprimir ticket</button>${sale.status==='completed'?`<button type="button" class="secondary" data-fiscal-sale="${esc(id)}">Boleta / factura</button>`:''}</div></div>`;ctx.dialogs.open({key:'receipt',title:sale.status==='voided'?'Venta eliminada':'Ticket de venta',body:html,focus:'[data-print]'});}
 async function click(b){if(await orderUI.click(b))return true;if(await saleHistory.click(b))return true;if(b.hasAttribute('data-tender')){payment.received=b.dataset.tender==='exact'?String(payment.cash):b.dataset.tender;updatePaymentView();return true;}if(b.dataset.favorite){const ids=favorites(),id=b.dataset.favorite;localStorage.setItem(favoriteKey(),JSON.stringify(ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]));document.querySelector('#sale-products').innerHTML=catalogue();return true;}if(await voiceSale.click(b))return true;const {data}=state();if(b.hasAttribute('data-open-checkout')){openCheckout();return true;}if(b.hasAttribute('data-reduce-product')){const id=b.dataset.reduceProduct;reduceProduct(id);const card=[...document.querySelectorAll('.product-card')].find(c=>c.querySelector('[data-add-product]')?.dataset.addProduct===id);(card?.querySelector('[data-reduce-product]')||card?.querySelector('.product-tile'))?.focus({preventScroll:true});return true;}if(b.hasAttribute('data-add-product')){addProduct(b.dataset.addProduct);return true;}if(b.hasAttribute('data-sale-category')){saleCategory=b.dataset.saleCategory;saleLimit=12;document.querySelector('#sale-products').innerHTML=catalogue();document.querySelectorAll('[data-sale-category]').forEach(x=>{const selected=x.dataset.saleCategory===saleCategory;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected));});return true;}if(b.hasAttribute('data-more-products')){saleLimit+=12;document.querySelector('#sale-products').innerHTML=catalogue();return true;}if(b.hasAttribute('data-payment-mode')){payment.mode=b.dataset.paymentMode;payment.manual=false;payment.autoCash=false;if(payment.mode==='yape')payment.received='';refreshCheckout('[data-payment-mode="'+payment.mode+'"]');ctx.flush();return true;}if(b.hasAttribute('data-cart-step')){const index=Number(b.dataset.cartStep),line=cart[index];if(!line)return true;const qty=Math.round((line.qty+Number(b.dataset.delta))*1000)/1000;if(qty<=0)cart.splice(index,1);else{if(qty>expected(line.product_id))throw Error('Stock insuficiente.');line.qty=qty;}initializePayment();refreshCart();return true;}if(b.dataset.orderDetail){await detail(b.dataset.orderDetail);return true;}if(b.hasAttribute('data-cart-remove')){cart.splice(Number(b.dataset.cartRemove),1);initializePayment();refreshCart();return true;}if(b.dataset.receipt){receipt(b.dataset.receipt);return true;}if(b.hasAttribute('data-print')){window.print();return true;}return false;}
 function input(e){void orderUI.input(e).catch(err=>notice(err.message,true));if(saleHistory.input(e))return;if(voiceSale.input(e))return;if(e.target.hasAttribute('data-sale-search')){if(e.type!=='input')return;saleSearch=e.target.value;saleLimit=12;document.querySelector('#sale-products').innerHTML=catalogue();return;}if(e.target.hasAttribute('data-cart-qty')){if(e.type!=='change')return;const line=cart[Number(e.target.dataset.cartQty)],qty=Number(e.target.value),p=state().data.products.find(p=>p.id===line?.product_id);if(!line||!p)return;if(!validQty(p,qty)||qty>expected(line.product_id)){e.target.value=line.qty;notice('Cantidad inválida o stock insuficiente.',true);return;}line.qty=qty;e.target.closest('.cart-line').querySelector('.cart-amount').textContent=money(lineTotal(line.product_id,qty));if(!payment.manual){payment.cash=payment.mode==='yape'?'0':String(Math.max(0,netTotal()));payment.yape=payment.mode==='yape'?String(Math.max(0,netTotal())):'0';}updatePaymentView();refreshCatalogue();return;}if(e.target.dataset.filter){const name=e.target.dataset.filter;filters[name==='order-store'?'store':name]=e.target.value;applyFilters();}if(e.target.closest('[data-form="open_shift"],[data-form="final_counts"]')&&dataUuid(e.target.name)){const {storeId,shift}=state();const opening=!!e.target.closest('[data-form="open_shift"]');countDrafts.set(`${storeId}/${opening?'opening':shift?.id}/${e.target.name}`,e.target.value);}if(e.target.closest('[data-form="sale"]')){const name=e.target.name;if(name in payment)payment[name]=e.target.value;const total=netTotal();if(name==='cash'||name==='yape'){payment.manual=true;payment.autoCash=false;if(payment.mode==='mixed'){if(name==='cash')payment.yape=String(Math.max(0,Math.round((total-Number(payment.cash))*100)/100));else payment.cash=String(Math.max(0,Math.round((total-Number(payment.yape))*100)/100));}}if(name==='discount'&&!payment.manual){payment.cash=payment.mode==='yape'?'0':String(Math.max(0,total));payment.yape=payment.mode==='yape'?String(Math.max(0,total)):'0';}updatePaymentView();}}
 const dataUuid=value=>/^[0-9a-f-]{36}$/i.test(value||'');
 function dashboard(){const {data,shift}=state();if(!shift)return ctx.legacyInicio().replace('<div class="fields">',`<div class="fields">${field('Método de ventas',select('sales_mode',[['direct','Ventas individuales'],['count','Ventas por conteo físico']]))}`);
  if(shift.sales_mode!=='direct')return ctx.legacyInicio();const entries=data.cash.filter(e=>e.shift_id===shift.id);const total=(data.sales||[]).filter(s=>s.shift_id===shift.id&&s.status==='completed').reduce((n,s)=>n+Number(s.total),0);const yape=entries.filter(e=>e.method==='yape').reduce((n,e)=>n+(['order_refund','sale_refund'].includes(e.kind)?-1:1)*Number(e.amount),0);
  return `<div class="cards"><div class="card"><small>Turno · ventas individuales</small><div class="metric">${esc(shift.label)}</div><p>${date(shift.opened_at)}</p></div><div class="card"><small>Ventas registradas</small><div class="metric">${money(total)}</div></div><div class="card"><small>Yape neto del turno</small><div class="metric">${money(yape)}</div></div></div><div class="grid"><div class="card"><h2>Cobrar productos</h2><button data-nav="ventas">Nueva venta</button></div><div class="card"><h2>Pedidos y adelantos</h2><button data-nav="pedidos">Ver pedidos</button></div></div>`;
 }
 function closing(){const {shift,preview,data,canClose}=state();if(shift&&!canClose)return '<div class="warn">Puedes registrar ventas y conteos en este turno. El responsable o un encargado debe realizar el cierre.</div>';if(!shift||shift.sales_mode!=='direct'||!preview||preview.error)return ctx.legacyClose();const rows=[['Fondo inicial',preview.opening_float],['Ventas cobradas en efectivo',preview.cash_sales],['Pedidos cobrados en efectivo',preview.cash_orders],['Otros ingresos',preview.other_income],['Devoluciones en efectivo',-preview.cash_refunds],['Egresos',-preview.expenses],['Retiros',-preview.pickups]];
  const diffs=sortProducts(data.counts.filter(c=>c.shift_id===shift.id&&expected(c.product_id)!==Number(c.closing_qty)),data.products,{product:c=>indexes().products.get(c.product_id),price:c=>c.price_snapshot});return `<div class="grid"><div class="card"><h2>Caja por cobros registrados</h2>${rows.map(([l,n])=>`<div class="summaryrow"><span>${l}</span><strong>${money(n)}</strong></div>`).join('')}<div class="summaryrow total"><span>Efectivo esperado</span><strong>${money(preview.expected_cash)}</strong></div><p>Ventas netas: ${money(preview.sales)} · Yape de ventas: ${money(preview.yape_sales)}</p>${diffs.length?`<div class="warn">Hay ${diffs.length} productos con diferencias. Explica el motivo para cerrar.</div>${table(['Producto','Esperado','Contado','Falta / sobra'],diffs.map(c=>row([esc(h.productName(c.product_id)),esc(expected(c.product_id)),esc(c.closing_qty),esc(Number(c.closing_qty)-expected(c.product_id))])))}`:'<p class="badge">Inventario coincide con los movimientos registrados</p>'}</div><div class="card"><h2>Contar efectivo y cerrar</h2><form data-form="close_shift">${field('Sencillo para el siguiente turno',qtyInput('float_left',200,'0.01'))}${field('Efectivo que se deja en bolsa',qtyInput('bag_amount','','0.01'))}<div id="difference" class="warn">Ingresa el efectivo contado.</div>${field('Explicación de diferencias',`<textarea name="explanation" ${diffs.length?'required':''}></textarea>`)}${confirmCount('Confirmo el conteo físico y el dinero. El turno quedará cerrado.')}<button>Cerrar turno</button></form></div></div>`;
 }
 function applyVoice(p){ensureCartShift();for(const l of p.lines){const product=state().data.products.find(x=>x.id===l.product_id);if(!product||!validQty(product,l.qty)||l.qty>expected(l.product_id))throw Error('Cambió el stock. Actualiza y vuelve a revisar la venta.');}cart=p.lines.map(l=>({...l}));payment={...cleanPayment(),discount:String(p.discount),cash:String(p.pay.cash),yape:String(p.pay.yape),mode:p.payment.mode,manual:p.payment.mode==='mixed'||p.payment.yape!==null,autoCash:p.payment.mode!=='yape',received:p.pay.received===null?'':String(p.pay.received),voiceTranscript:p.transcript,note:p.discount?'Descuento dictado y confirmado.':''};}
 async function confirmVoice(p,holder){const cash=p.pay.cash,audit=p.pay.received===null?'':`Efectivo entregado ${money(p.pay.received)}; vuelto ${money(p.pay.change)}.`;const result=await operate('sale',{shift_id:state().shift.id,lines:p.lines,cash,yape:p.pay.yape,discount:p.discount,reference:'',note:[p.discount?'Descuento dictado y confirmado.':'',audit,`Dictado original: ${p.transcript}`].filter(Boolean).join('\n')},holder);cart=[];payment=cleanPayment();voiceSale.reset();ctx.flush();await ctx.load();ctx.render();receipt(result.id);notice('Venta guardada. Stock y caja actualizados.');}
 const voiceSale=createSaleVoice({state,esc,money,notice,render:ctx.render,picker:(...args)=>products(...args),openCheckout,confirm:confirmVoice,cartCount:()=>cart.length,apply:applyVoice,products:()=>{const {data,shift}=state();return data.products.filter(p=>data.counts.some(c=>c.shift_id===shift?.id&&c.product_id===p.id)).map(p=>({...p,voicePrice:priceFor(p.id),voiceStock:expected(p.id)}));}});
 function snapshot(){rememberCheckout();return {cart,cartShift,payment,checkoutRequest,countDrafts:[...countDrafts],voice:voiceSale.snapshot()};}
 function restore(raw){if(!raw)return;cart=Array.isArray(raw.cart)?raw.cart:[];cartShift=raw.cartShift||state().shift?.id||null;payment={...cleanPayment(),...(raw.payment||{})};checkoutRequest=raw.checkoutRequest||{};countDrafts=new Map(raw.countDrafts||[]);voiceSale.restore(raw.voice);}
 return {snapshot,restore,detail,orders,sales,countTable,dashboard,closing,applyFilters,submit,click,input,expected,ensureCartShift,updatePaymentView,isListening:voiceSale.isListening,stopVoice:voiceSale.cancel,afterRender:()=>{orderUI.mount();checkoutObserver?.disconnect();const button=document.querySelector('.sales-checkout-inline');checkoutButtonVisible=true;if(button&&'IntersectionObserver'in window){checkoutObserver=new IntersectionObserver(entries=>{checkoutButtonVisible=entries[0].isIntersecting;updateSaleSummary();});checkoutObserver.observe(button);}updateSaleSummary();},clearCart:()=>{orderUI.clear();saleHistory.clear();cart=[];cartShift=null;payment=cleanPayment();checkoutRequest={};voiceSale.reset();},clearCounts:()=>countDrafts.clear()};
}
